                          <circle cx="7.4" cy="8.4" r="4.2" fill="#F06A6A"></circle>
                          <circle cx="16.6" cy="8.4" r="4.2" fill="#F06A6A"></circle>
                        </svg>
                      </span>
                      <span class="fmstr-cmp-mdy-set__int-name">Asana</span>
                      <span class="fmstr-cmp-mdy-set__int-btn">Connect</span>
                    </div>
                    <div class="fmstr-cmp-mdy-set__int-row">
                      <span class="fmstr-cmp-mdy-set__int-logo" aria-label="ClickUp">
                        <svg width="14" height="14" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">
                          <path
