}
.fmstr-cmp-mdy-hero__arrow-line {
  position: absolute;
  left: 0;
  right: 0;
  top: 50%;
  height: 2px;
  background: repeating-linear-gradient(
    to right,
    var(--c-violet-500) 0,
    var(--c-violet-500) 6px,
    transparent 6px,
    transparent 11px
  );
  transform: translateY(-50%);
}
.fmstr-cmp-mdy-hero__arrow-tip {
  position: relative;
  width: 30px;
  height: 30px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--c-violet-500), var(--c-violet-700));
  color: #fff;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 6px 14px rgba(127, 86, 217, 0.32);
  z-index: 1;
}

/* monday board mockup */
.fmstr-cmp-mdy-hero__board {
  padding: 0 20px 20px;
  border-top: 1px dashed var(--c-border);
  padding-top: 16px;
  margin-top: -4px;
}
.fmstr-cmp-mdy-hero__board-header {
  display: grid;
  grid-template-columns: 14px 1fr 70px 70px;
  gap: 10px;
  align-items: center;
  padding: 4px 10px;
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--c-fg-3);
  margin-bottom: 4px;
}
.fmstr-cmp-mdy-hero__board-row {
  display: grid;
  grid-template-columns: 14px 1fr 70px 70px;
  gap: 10px;
  align-items: center;
  padding: 8px 10px;
  background: #f9fafb;
  border-radius: 8px;
  font-size: 12px;
  margin-bottom: 4px;
}
.fmstr-cmp-mdy-hero__board-stripe {
  width: 4px;
  height: 18px;
  border-radius: 2px;
}
.fmstr-cmp-mdy-hero__board-stripe--new {
  background: var(--c-mdy-green);
}
.fmstr-cmp-mdy-hero__board-stripe--work {
  background: var(--c-mdy-yellow);
}
.fmstr-cmp-mdy-hero__board-stripe--hot {
  background: var(--c-mdy-red);
}
.fmstr-cmp-mdy-hero__board-item {
  color: var(--c-fg-1);
  font-weight: 600;
}
.fmstr-cmp-mdy-hero__board-status {
  padding: 3px 8px;
  border-radius: 4px;
  color: #ffffff;
  font-size: 10.5px;
  font-weight: 700;
  text-align: center;
}
.fmstr-cmp-mdy-hero__board-status--new {
  background: var(--c-mdy-green);
}
.fmstr-cmp-mdy-hero__board-status--work {
  background: var(--c-mdy-yellow);
  color: #5d4400;
}
.fmstr-cmp-mdy-hero__board-status--hot {
  background: var(--c-mdy-red);
}
.fmstr-cmp-mdy-hero__board-owner {
  font-size: 10.5px;
  color: var(--c-fg-3);
  text-align: right;
}

.fmstr-cmp-mdy-hero__timer {
  position: absolute;
  right: -14px;
  bottom: -22px;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 10px 14px;
  background: #ffffff;
  border: 1px solid var(--c-edge);
  border-radius: 9999px;
  font-size: 12.5px;
  font-weight: 600;
  color: var(--c-violet-700);
  box-shadow: var(--c-shadow-md);
}
.fmstr-cmp-mdy-hero__timer-num {
  font-variant-numeric: tabular-nums;
  color: var(--c-fg-1);
  font-weight: 700;
}

@media (max-width: 980px) {
  .fmstr-cmp-mdy-hero__container {
    grid-template-columns: 1fr;
    gap: 48px;
  }
  .fmstr-cmp-mdy-hero__copy {
    max-width: 100%;
  }
  .fmstr-cmp-mdy-hero__timer {
    right: 8px;
    bottom: -18px;
  }
}
@media (max-width: 760px) {
  .fmstr-cmp-mdy-hero {
    padding: 72px 16px 64px;
  }
  .fmstr-cmp-mdy-hero__ctas {
    flex-direction: column;
    align-items: stretch;
  }
  .fmstr-cmp-mdy-hero a.fmstr-cmp-mdy-hero__cta-primary,
  .fmstr-cmp-mdy-hero a.fmstr-cmp-mdy-hero__cta-secondary {
    justify-content: center;
  }
  .fmstr-cmp-mdy-hero__timer {
    position: static;
    margin-top: 18px;
  }
  .fmstr-cmp-mdy-hero__pipe {
    grid-template-columns: 1fr;
    gap: 12px;
  }
  .fmstr-cmp-mdy-hero__arrow {
    display: none;
  }
}

/* host-link-override */
.fmstr-cmp-mdy-syncs a {
  color: var(--c-violet-600) !important;
