}
.fmstr-cmp-mdy-syncs a:hover {
  text-decoration: underline !important;
}

.fmstr-cmp-mdy-syncs {
  --c-bg: #ffffff;
  --c-soft: #f9fafb;
  --c-tint: #f7f3ff;
  --c-edge: #e4d7ff;
  --c-fg-1: #101828;
  --c-fg-2: #475467;
  --c-fg-3: #697586;
  --c-violet-500: #7f56d9;
  --c-violet-600: #6941c6;
  --c-violet-700: #5b34b1;
  --c-border: #eaecf0;
  --c-shadow-sm: 0 1px 3px rgba(16, 24, 40, 0.05);
  --c-shadow-md: 0 4px 20px rgba(16, 24, 40, 0.06);

  background: var(--c-bg);
  padding: 88px 24px;
  font-family: inherit;
  overflow-x: hidden;
  color: var(--c-fg-1);
}
.fmstr-cmp-mdy-syncs *,
.fmstr-cmp-mdy-syncs *::before,
.fmstr-cmp-mdy-syncs *::after {
  box-sizing: border-box;
}
.fmstr-cmp-mdy-syncs > *,
.fmstr-cmp-mdy-syncs > * > * {
