}

.fmstr-cmp-mdy-syncs__container {
  max-width: 1180px;
  margin: 0 auto;
}

.fmstr-cmp-mdy-syncs__header {
  max-width: 820px;
  margin: 0 auto 48px;
  text-align: center;
}
.fmstr-cmp-mdy-syncs__h2 {
  margin: 0 0 14px;
  font-size: clamp(28px, 3.6vw, 42px);
  line-height: 1.12;
  letter-spacing: -0.02em;
  font-weight: 700;
  color: var(--c-fg-1);
}
.fmstr-cmp-mdy-syncs__sub {
  margin: 0;
  font-size: 17px;
  line-height: 1.6;
  color: var(--c-fg-2);
}

.fmstr-cmp-mdy-syncs__grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
  position: relative;
}

.fmstr-cmp-mdy-syncs__card {
  background: #ffffff;
  border: 1px solid var(--c-border);
  border-radius: 16px;
  box-shadow: var(--c-shadow-sm);
  padding: 28px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  position: relative;
  z-index: 1;
}

.fmstr-cmp-mdy-syncs__card-head {
  display: flex;
  align-items: center;
  gap: 12px;
  padding-bottom: 16px;
  border-bottom: 1px solid var(--c-border);
}
.fmstr-cmp-mdy-syncs__logo {
  height: 36px;
  padding: 0 14px;
  border-radius: 10px;
  background: #ffffff;
  border: 1px solid var(--c-border);
