  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.fmstr-cmp-mdy-syncs__logo svg,
.fmstr-cmp-mdy-syncs__logo img {
  display: block;
  height: 18px;
  width: auto;
}
.fmstr-cmp-mdy-syncs__h3 {
