  font-size: 18px;
  line-height: 1.3;
  font-weight: 700;
  color: var(--c-fg-1);
}

.fmstr-cmp-mdy-syncs__list {
  margin: 0;
  padding: 0;
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.fmstr-cmp-mdy-syncs__item {
  display: grid;
  grid-template-columns: 20px 1fr;
  gap: 10px;
  align-items: start;
  font-size: 14.5px;
  line-height: 1.55;
  color: var(--c-fg-2);
}
.fmstr-cmp-mdy-syncs__item-icon {
  margin-top: 2px;
  color: var(--c-violet-600);
  flex-shrink: 0;
}
.fmstr-cmp-mdy-syncs__item-label {
  color: var(--c-fg-1);
  font-weight: 600;
}

.fmstr-cmp-mdy-syncs__arrow {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--c-violet-500), var(--c-violet-700));
  color: #ffffff;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 10px 24px rgba(127, 86, 217, 0.28);
  z-index: 2;
}

.fmstr-cmp-mdy-syncs__caveat {
  margin: 28px auto 0;
  max-width: 820px;
  padding: 16px 22px;
  background: var(--c-tint);
  border: 1px solid var(--c-edge);
  border-radius: 12px;
  font-size: 14.5px;
  line-height: 1.6;
  color: var(--c-fg-2);
  text-align: center;
}

@media (max-width: 880px) {
  .fmstr-cmp-mdy-syncs__grid {
    grid-template-columns: 1fr;
    gap: 16px;
  }
  .fmstr-cmp-mdy-syncs__arrow {
    top: auto;
    left: 50%;
