}
.fmstr-cmp-mdy-set__sub {
  margin: 0;
  font-size: 17px;
  line-height: 1.6;
  color: var(--c-fg-2);
}

.fmstr-cmp-mdy-set__grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}

.fmstr-cmp-mdy-set__card {
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding: 28px;
  background: #ffffff;
  border: 1px solid var(--c-border);
  border-radius: 16px;
  box-shadow: var(--c-shadow-sm);
}

.fmstr-cmp-mdy-set__num {
  display: inline-flex;
