}

.fmstr-cmp-mdy-set__visual {
  margin-top: auto;
  padding: 14px;
  background: var(--c-soft);
  border: 1px solid var(--c-border);
  border-radius: 10px;
  font-size: 12.5px;
}

/* Step 1: integration row */
.fmstr-cmp-mdy-set__int-row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 10px;
  background: #ffffff;
  border: 1px solid var(--c-border);
  border-radius: 8px;
}
.fmstr-cmp-mdy-set__int-row + .fmstr-cmp-mdy-set__int-row {
  margin-top: 6px;
}
.fmstr-cmp-mdy-set__int-logo {
  height: 28px;
  padding: 0 8px;
  border-radius: 6px;
  background: #ffffff;
  border: 1px solid var(--c-border);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.fmstr-cmp-mdy-set__int-logo svg,
.fmstr-cmp-mdy-set__int-logo img {
  display: block;
  height: 14px;
  width: auto;
}
.fmstr-cmp-mdy-set__int-name {
  font-size: 12.5px;
  color: var(--c-fg-1);
  font-weight: 500;
  flex: 1;
}
.fmstr-cmp-mdy-set__int-btn {
  padding: 4px 10px;
  background: var(--c-violet-500);
  color: #ffffff;
  border-radius: 9999px;
  font-size: 11px;
  font-weight: 600;
}
.fmstr-cmp-mdy-set__int-btn--done {
  background: #ecfdf3;
  color: #027a48;
}

/* Step 2: field mapping */
.fmstr-cmp-mdy-set__map {
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.fmstr-cmp-mdy-set__map-row {
  display: grid;
  grid-template-columns: 1fr 18px 1fr;
  gap: 8px;
  align-items: center;
  font-size: 11.5px;
}
.fmstr-cmp-mdy-set__map-from {
  padding: 6px 8px;
  background: var(--c-tint);
  border-radius: 6px;
  color: var(--c-violet-700);
  font-weight: 600;
}
.fmstr-cmp-mdy-set__map-arrow {
  text-align: center;
  color: var(--c-violet-500);
  font-weight: 700;
}
.fmstr-cmp-mdy-set__map-to {
  padding: 6px 8px;
  border-radius: 6px;
  font-weight: 600;
  color: #ffffff;
}
.fmstr-cmp-mdy-set__map-to--status {
  background: var(--c-mdy-green);
}
.fmstr-cmp-mdy-set__map-to--text {
  background: #2c3e50;
}
.fmstr-cmp-mdy-set__map-to--number {
  background: #007eb5;
}
.fmstr-cmp-mdy-set__map-to--file {
  background: #ab47bc;
}

/* Step 3: confirmation */
.fmstr-cmp-mdy-set__confirm {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 12px;
  background: #ecfdf3;
  border: 1px solid #abefc6;
  border-radius: 8px;
  font-size: 12px;
  color: #027a48;
  font-weight: 600;
}
.fmstr-cmp-mdy-set__confirm-item {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 10px;
  margin-top: 6px;
  background: #ffffff;
  border: 1px solid var(--c-border);
  border-radius: 8px;
  font-size: 12px;
  color: var(--c-fg-1);
}
.fmstr-cmp-mdy-set__confirm-stripe {
  width: 4px;
  height: 18px;
  border-radius: 2px;
  background: var(--c-mdy-green);
}
.fmstr-cmp-mdy-set__confirm-name {
  font-weight: 600;
  flex: 1;
}
.fmstr-cmp-mdy-set__confirm-status {
  padding: 2px 7px;
  background: var(--c-mdy-green);
  color: #ffffff;
  border-radius: 4px;
  font-size: 10.5px;
  font-weight: 700;
}

.fmstr-cmp-mdy-set__cta-row {
  margin-top: 40px;
  text-align: center;
}
.fmstr-cmp-mdy-set a.fmstr-cmp-mdy-set__cta {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 14px 22px;
  background: var(--c-violet-500) !important;
  color: #ffffff !important;
  border-radius: 9999px;
  font-size: 15.5px;
  font-weight: 600;
  box-shadow: 0 6px 16px rgba(127, 86, 217, 0.28);
}
.fmstr-cmp-mdy-set a.fmstr-cmp-mdy-set__cta:hover {
  background: var(--c-violet-600) !important;
}

.fmstr-cmp-mdy-set__fallback {
  margin: 24px auto 0;
  max-width: 720px;
  padding: 14px 18px;
  background: #ffffff;
  border: 1px dashed var(--c-border);
  border-radius: 10px;
  font-size: 13.5px;
  line-height: 1.55;
  color: var(--c-fg-3);
  text-align: center;
}

@media (max-width: 1000px) {
  .fmstr-cmp-mdy-set__grid {
    grid-template-columns: 1fr;
    max-width: 520px;
    margin: 0 auto;
  }
}
@media (max-width: 640px) {
  .fmstr-cmp-mdy-set {
